package main

import (
	"os"
	"path/filepath"
	"runtime"
	"testing"

	derivationv1 "github.com/plantonhq/planton/finops/catalogkindcostderivation/v1"
	"github.com/plantonhq/planton/pkg/finops/costestimate"
)

// TestCostEstimateDrift is the freshness gate for the committed estimate
// documents: one whole-tree generation must reproduce every committed file
// byte-identically, every generated file must be committed, no committed
// estimate may be orphaned (generated by nothing), and the cross-artifact
// coherence checks (price references, dead prices, unit/currency/region
// agreements) must all hold. An edited model, a refreshed price book, or a
// hand-edited estimate fails the gate until regeneration reconciles them.
//
// On drift: PLANTON_REGEN_COST_ESTIMATES=1 go test ./pkg/finops/estimategen -run TestCostEstimateDrift
// (or `make generate-cost-estimates`).
func TestCostEstimateDrift(t *testing.T) {
	root := repoRoot(t)
	if _, err := os.Stat(filepath.Join(root, "catalog")); err != nil {
		t.Skip("catalog source tree not present (bazel sandbox); runs under go test and the lint.catalog-data lane")
	}

	summary, err := Generate(root)
	if err != nil {
		t.Fatalf("generate: %v", err)
	}
	for _, problem := range summary.Problems {
		t.Errorf("coherence: %s", problem)
	}

	regen := os.Getenv("PLANTON_REGEN_COST_ESTIMATES") != ""
	if regen && len(summary.Problems) > 0 {
		t.Fatal("refusing to regenerate over coherence problems -- fix the inputs first")
	}
	for _, path := range summary.SortedPaths() {
		want := summary.Files[path]
		target := filepath.Join(root, path)
		if regen {
			if err := os.WriteFile(target, []byte(want), 0644); err != nil {
				t.Fatalf("write %s: %v", target, err)
			}
			continue
		}
		got, err := os.ReadFile(target)
		if err != nil {
			t.Errorf("%s is generated but not committed -- run `make generate-cost-estimates`: %v", path, err)
			continue
		}
		if string(got) != want {
			t.Errorf("%s is out of sync with its model and price book -- run `make generate-cost-estimates`", path)
		}
	}

	for _, path := range committedEstimateFiles(t, root) {
		if _, ok := summary.Files[path]; !ok {
			t.Errorf("%s is committed but no longer generated (model removed or renamed?) -- delete it", path)
		}
	}
}

// TestLookupStaticCredit pins the dead-price sweep's family credit: a
// value-keyed entry a derivation's lookup COULD select is a live
// reference even when no committed preset exercises it -- the property
// that lets a price family grow ahead of the preset corpus -- while
// entries the lookup could never select (wrong constant identity, extra
// attribute keys, missing keys) stay dead weight.
func TestLookupStaticCredit(t *testing.T) {
	lookup := &derivationv1.PriceLookup{
		ServiceName: "Amazon Relational Database Service",
		PricingUnit: "hours",
		Attributes: []*derivationv1.AttributeBinding{
			{Key: "engine", Value: &derivationv1.AttributeBinding_Constant{Constant: "aurora-postgresql"}},
			{Key: "instance_class", Value: &derivationv1.AttributeBinding_FromField{FromField: "instance_class"}},
		},
	}
	cases := []struct {
		name       string
		attributes map[string]string
		want       bool
	}{
		{"family member no preset selects", map[string]string{"engine": "aurora-postgresql", "instance_class": "db.r6g.4xlarge"}, true},
		{"wrong constant identity", map[string]string{"engine": "aurora-mysql", "instance_class": "db.r6g.large"}, false},
		{"extra attribute key", map[string]string{"engine": "aurora-postgresql", "instance_class": "db.r6g.large", "deployment": "multi-az"}, false},
		{"missing bound key", map[string]string{"engine": "aurora-postgresql"}, false},
	}
	for _, c := range cases {
		if got := lookupCouldSelect(lookup, c.attributes); got != c.want {
			t.Errorf("%s: lookupCouldSelect = %v, want %v", c.name, got, c.want)
		}
	}
}

// committedEstimateFiles lists every committed estimate document, so the
// gate catches orphans in both directions.
func committedEstimateFiles(t *testing.T, root string) []string {
	t.Helper()
	matches, err := filepath.Glob(filepath.Join(root, costestimate.Dir, "*.yaml"))
	if err != nil {
		t.Fatal(err)
	}
	var files []string
	for _, match := range matches {
		rel, err := filepath.Rel(root, match)
		if err != nil {
			t.Fatal(err)
		}
		files = append(files, rel)
	}
	return files
}

// repoRoot walks up from this test file to the directory containing go.mod.
func repoRoot(t *testing.T) string {
	t.Helper()
	_, thisFile, _, ok := runtime.Caller(0)
	if !ok {
		t.Fatal("runtime.Caller failed")
	}
	dir := filepath.Dir(thisFile)
	for {
		if _, err := os.Stat(filepath.Join(dir, "go.mod")); err == nil {
			return dir
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			if os.Getenv("TEST_WORKSPACE") != "" {
				t.Skip("skipping drift gate under the Bazel sandbox: the repo checkout is not available; the gate runs via `go test`")
			}
			t.Fatal("could not locate repo root (go.mod)")
		}
		dir = parent
	}
}
